// add+modify_eas_records.hpp
#pragma once

#include <filesystem>
#include <map>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

#include "eas_common.hpp"

using namespace sqlgen;
using namespace sqlgen::literals;

// Helper: map table name -> C++ type used with sqlgen
inline const std::map<std::string, std::string> kEasTableTypes = {
    {"Student", "Student"}, {"Course", "Course"},
    {"Score", "Score"},     {"Major", "Major"}};

// Generic insert using sqlgen::write.
// T must be one of: Student, Course, Score, Major.
template <typename T>
void add_eas_records(const std::string& table_name,
                     const std::vector<T>& records) {
  if (records.empty()) {
    return;
  }

  // Ensure the requested table_name matches T
  const std::string type_name = typeid(T).name();  // only for debug checks
  (void)type_name;  // avoid unused warning in release

  // In this simple implementation we trust the caller that T matches
  // table_name, because sqlgen binds by struct type, not by name.
  // We only guard against obviously wrong names.
  if (table_name != "Student" && table_name != "Course" &&
      table_name != "Score" && table_name != "Major") {
    throw std::runtime_error("Unsupported table name: " + table_name);
  }

  // Connect and write
  sqlgen::sqlite::connect(db_path)
      .and_then([&](auto&& conn) {
        return sqlgen::write(conn, records);
      })
      .value();  // propagate exceptions on failure
}

// Modify a single column of a row identified by its primary key.
// record_id is passed as string because primary keys differ in type.
inline void modify_eas_records_by_id(const std::string& table_name,
                                     const std::string& record_id,
                                     const std::string& col_name,
                                     const std::string& new_value) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to DB first
  auto conn_res = sqlgen::sqlite::connect(db_path);
  if (!conn_res) {
    conn_res.value();  // will throw stored error
  }
  auto conn = conn_res.value();

  if (table_name == "Student") {
    // Primary key: SNo (Varchar<10>) -> treat id as text
    if (col_name == "SName") {
      auto set_clause = "SName"_c.set(new_value);
      auto where_clause = where("SNo"_c == new_value);  // incorrect if id != new_value
      (void)set_clause;
      (void)where_clause;
    }

    auto where_clause = where("SNo"_c == record_id);

    // We must guess column type at compile-time; here, use text for simplicity.
    // sqlgen expects strongly typed sets, so we limit to a few known columns.
    if (col_name == "SName") {
      auto set_clause = "SName"_c.set(new_value);
      sqlgen::update<Student>(set_clause)(conn).and_then([&](auto&&) {
        return Result<Ref<decltype(conn.get())>>(conn);
      });
    } else if (col_name == "Sex") {
      int v = std::stoi(new_value);
      auto set_clause = "Sex"_c.set(v);
      sqlgen::update<Student>(set_clause) | where_clause (conn).value();
    } else if (col_name == "Remark") {
      auto set_clause = "Remark"_c.set(new_value);
      sqlgen::update<Student>(set_clause) | where_clause (conn).value();
    } else {
      throw std::runtime_error(
          "Unsupported column for Student in this example: " + col_name);
    }

  } else if (table_name == "Course") {
    // Primary key: CID (uint32_t, auto_incr)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto where_clause = where("CID"_c == id_val);

    if (col_name == "CName") {
      auto set_clause = "CName"_c.set(new_value);
      sqlgen::update<Course>(set_clause) | where_clause (conn).value();
    } else if (col_name == "Term") {
      int v = std::stoi(new_value);
      auto set_clause = "Term"_c.set(v);
      sqlgen::update<Course>(set_clause) | where_clause (conn).value();
    } else if (col_name == "CTime") {
      int v = std::stoi(new_value);
      auto set_clause = "CTime"_c.set(v);
      sqlgen::update<Course>(set_clause) | where_clause (conn).value();
    } else if (col_name == "Credit") {
      int v = std::stoi(new_value);
      auto set_clause = "Credit"_c.set(v);
      sqlgen::update<Course>(set_clause) | where_clause (conn).value();
    } else {
      throw std::runtime_error(
          "Unsupported column for Course in this example: " + col_name);
    }

  } else if (table_name == "Score") {
    // Primary key: ScID (uint32_t, auto_incr)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto where_clause = where("ScID"_c == id_val);

    if (col_name == "Score") {
      double v = std::stod(new_value);
      auto set_clause = "Score"_c.set(v);
      sqlgen::update<Score>(set_clause) | where_clause (conn).value();
    } else if (col_name == "SNo") {
      auto set_clause = "SNo"_c.set(new_value);
      sqlgen::update<Score>(set_clause) | where_clause (conn).value();
    } else if (col_name == "CID") {
      uint32_t v = static_cast<uint32_t>(std::stoul(new_value));
      auto set_clause = "CID"_c.set(v);
      sqlgen::update<Score>(set_clause) | where_clause (conn).value();
    } else {
      throw std::runtime_error(
          "Unsupported column for Score in this example: " + col_name);
    }

  } else if (table_name == "Major") {
    // Primary key: MID (uint32_t)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto where_clause = where("MID"_c == id_val);

    if (col_name == "MName") {
      auto set_clause = "MName"_c.set(new_value);
      sqlgen::update<Major>(set_clause) | where_clause (conn).value();
    } else {
      throw std::runtime_error(
          "Unsupported column for Major in this example: " + col_name);
    }

  } else {
    throw std::runtime_error("Unsupported table name: " + table_name);
  }
}

// Delete by primary key (record_id given as string, converted per table).
inline void delete_eas_records_by_id(const std::string& table_name,
                                     const std::string& record_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  auto conn_res = sqlgen::sqlite::connect(db_path);
  if (!conn_res) {
    conn_res.value();  // will throw
  }
  auto conn = conn_res.value();

  if (table_name == "Student") {
    // PK: SNo (string)
    auto cond = where("SNo"_c == record_id);
    (sqlgen::delete_from<Student> | cond)(conn).value();

  } else if (table_name == "Course") {
    // PK: CID (uint32_t)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto cond = where("CID"_c == id_val);
    (sqlgen::delete_from<Course> | cond)(conn).value();

  } else if (table_name == "Score") {
    // PK: ScID (uint32_t)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto cond = where("ScID"_c == id_val);
    (sqlgen::delete_from<Score> | cond)(conn).value();

  } else if (table_name == "Major") {
    // PK: MID (uint32_t)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto cond = where("MID"_c == id_val);
    (sqlgen::delete_from<Major> | cond)(conn).value();

  } else {
    throw std::runtime_error("Unsupported table name: " + table_name);
  }
}
