// Delete by primary key (record_id given as string, converted per table).
inline void delete_eas_records_by_id(const std::string& table_name,
                                     const std::string& record_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  auto conn_res = sqlgen::sqlite::connect(db_path);
  if (!conn_res) {
    conn_res.value();  // will throw
  }
  auto conn = conn_res.value();

  if (table_name == "Student") {
    // PK: SNo (string)
    auto cond = where("SNo"_c == record_id);
    (sqlgen::delete_from<Student> | cond)(conn).value();

  } else if (table_name == "Course") {
    // PK: CID (uint32_t)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto cond = where("CID"_c == id_val);
    (sqlgen::delete_from<Course> | cond)(conn).value();

  } else if (table_name == "Score") {
    // PK: ScID (uint32_t)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto cond = where("ScID"_c == id_val);
    (sqlgen::delete_from<Score> | cond)(conn).value();

  } else if (table_name == "Major") {
    // PK: MID (uint32_t)
    uint32_t id_val = static_cast<uint32_t>(std::stoul(record_id));
    auto cond = where("MID"_c == id_val);
    (sqlgen::delete_from<Major> | cond)(conn).value();

  } else {
    throw std::runtime_error("Unsupported table name: " + table_name);
  }
}

