namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 *
 * Steps:
 * 1. Connect to SQLite database "test_db.sqlite".
 * 2. Drop Product table if it exists.
 * 3. Create Product table.
 * 4. Begin a transaction.
 * 5. Insert all products in a batch using sqlgen::write.
 * 6. Commit the transaction if everything succeeds.
 *
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  using namespace sqlgen;

  // 1. Connect to SQLite database.
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.value();

  // 2. Drop Product table if it exists.
  auto drop_res = (drop<Product> | if_exists)(conn);
  if (!drop_res) {
    return false;
  }

  // 3. Create Product table.
  auto create_res = create_table<Product>{.if_not_exists_ = false}(drop_res);
  if (!create_res) {
    return false;
  }

  // 4. Begin transaction.
  auto tx_res = begin_transaction(create_res);
  if (!tx_res) {
    return false;
  }
  auto tx = tx_res.value();

  // 5. Insert products in a batch inside the transaction.
  //    We use the transaction's connection handle.
  auto write_res = write(tx->conn(), products);
  if (!write_res) {
    // In case of failure, we rely on Transaction's destructor or
    // implementation to roll back if needed. We just signal failure.
    return false;
  }

  // 6. Commit transaction.
  auto commit_res = commit(tx);
  if (!commit_res) {
    return false;
  }

  return true;
}

}  // namespace batch_insert_products
