namespace delete_inactive_users {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::optional<sqlgen::DateTime> last_login;
  std::string status = "active";
};

int delete_inactive_users() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = connect("test_db.sqlite");
  if (!conn_res) {
    // Connection failed.
    return 0;
  }

  // Begin a transaction.
  auto tx_res = begin_transaction(conn_res);
  if (!tx_res) {
    // Could not start transaction.
    return 0;
  }

  // Build condition: last_login < DATE('2025-01-01')
  // We rely on the SQL function DATE('2025-01-01') as a raw SQL literal
  // by passing it as a string; sqlgen will treat it as a value expression.
  auto condition = "last_login"_c < std::string("DATE('2025-01-01')");

  // Perform the DELETE within the transaction.
  auto del_res = delete_from<User> | where(condition);
  auto after_delete = del_res(tx_res);
  if (!after_delete) {
    // Delete failed; transaction is not committed.
    return 0;
  }

  // Commit the transaction.
  auto commit_res = commit(tx_res);
  if (!commit_res) {
    // Commit failed.
    return 0;
  }

  // Indicate success.
  return 1;
}

} // namespace delete_inactive_users
