  struct Student {
    rfl::Field<"SNo",
               std::string,
               sqlgen::constraints<sqlgen::primary_key, sqlgen::not_null>>
        sno;

    rfl::Field<"SName",
               std::string,
               sqlgen::constraints<sqlgen::not_null>>
        sname;

    // Sex: int, NULL DEFAULT 1
    rfl::Field<"Sex",
