  // | Term   | int         | NULL DEFAULT 1                  |
  // | CTime  | int         | NULL                            |
  // | Credit | float       | NOT NULL DEFAULT 0              |
  struct Course {
    // SQLite auto-increment primary key
    rfl::Field<"CID",
               int,
               sqlgen::constraints<sqlgen::primary_key,
                                   sqlgen::auto_increment,
                                   sqlgen::not_null>>
        cid;

    rfl::Field<"CName",
               std::string,
               sqlgen::constraints<sqlgen::not_null>>
        cname;

    // Term: int, NULL DEFAULT 1
    rfl::Field<"Term",
