std::vector<ActiveUser> query_active_users_posts() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // On failure, return an empty vector (no exceptions in this snippet)
    return {};
  }

  auto& conn = *conn_res;

  // 2. Create User and Post tables (if they do not exist)
  auto create_res =
      create_table<User>(conn).if_not_exists_(true)(conn)  // returns Result<Ref<Connection>>
      .and_then([](auto& c) {
        return create_table<Post>(c).if_not_exists_(true)(c);
      });

  if (!create_res) {
    return {};
  }

  // 3. Build the query: users with at least one post between 2025-12-01 and 2025-12-31 (inclusive)
  const std::string start_date = "2025-12-01";
  const std::string end_date   = "2025-12-31";

  // Equivalent to:
  // SELECT DISTINCT u.user_id, u.username
  // FROM User u
  // INNER JOIN Post p ON u.user_id = p.user_id
  // WHERE p.created_at >= DATE('2025-12-01')
  //   AND p.created_at <= DATE('2025-12-31');

  auto query =
      select_from<User, "u">( // FROM User AS u
          "user_id"_t1, "username"_t1) // columns from alias t1 (u)
      | inner_join<Post, "p">(         // INNER JOIN Post AS p
            "user_id"_t1 ==
            "user_id"_t2)              // ON u.user_id = p.user_id
      | where(
            ("created_at"_t2 >= start_date) &&
            ("created_at"_t2 <= end_date))
      | to<std::vector<ActiveUser>>();

  auto res = query(conn);

  // 4. Return user information (ActiveUser objects)
  if (!res) {
    return {};
  }

  // Ensure distinctness at C++ level in case the query doesn't enforce it
  // (sqlgen doesn't expose DISTINCT directly in the snippets we have).
  std::vector<ActiveUser> distinct_users;
  distinct_users.reserve(res->size());

  for (const auto& u : *res) {
    bool exists = false;
    for (const auto& du : distinct_users) {
      if (du.user_id == u.user_id) {
        exists = true;
        break;
      }
    }
    if (!exists) {
      distinct_users.push_back(u);
    }
  }

  return distinct_users;
}

