namespace query_course_enrollment_stats {

struct Course {
  sqlgen::PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  sqlgen::PrimaryKey<int> enrollment_id;
  sqlgen::ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

// View to store course enrollment statistics
struct CourseStatsView {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn_res = connect("test_db.sqlite");

  if (!conn_res) {
    // On connection error, return empty vector (could also throw depending on requirements)
    return {};
  }

  auto conn = *conn_res;

  // 2. Create Course and Enrollment tables (if they don't already exist)
  // Note: The provided create_table helper supports an "if_not_exists_" flag.
  auto create_res =
      create_table<Course>{.if_not_exists_ = true}(conn)
          .and_then(create_table<Enrollment>{.if_not_exists_ = true});

  if (!create_res) {
    // On table-creation error, return empty vector
    return {};
  }

  // 3. Query the database to calculate number of students enrolled per course
  //    and average grade per course (ignoring NULLs).
  //
  // SQL equivalent:
  // SELECT c.title,
  //        COUNT(e.enrollment_id) AS student_count,
  //        AVG(e.grade)           AS avg_grade
  // FROM Course c
  // LEFT JOIN Enrollment e ON c.course_id = e.course_id
  // GROUP BY c.course_id, c.title;
  //
  // We'll express this with sqlgen, collect to CourseStatsView, then map.

  // Define column aliases via user literals:
  // c: Course, e: Enrollment
  using sqlgen::select_from;
  using sqlgen::to;
  using sqlgen::group_by;
  using sqlgen::as;
  using sqlgen::avg;
  using sqlgen::count;

  // Build and execute the query, collecting directly to a std::vector<CourseStatsView>.
  auto query_res =
      (select_from<Course, "c">("title"_t1,
                                // COUNT(e.enrollment_id) AS student_count
                                (count("enrollment_id"_t2) |
                                 as<"student_count">()),
                                // AVG(e.grade) AS avg_grade
                                (avg("grade"_t2) | as<"avg_grade">())) |
       // LEFT JOIN Enrollment e ON c.course_id = e.course_id
       sqlgen::transpilation::join_left<Enrollment, "e">(
           "course_id"_t1 == "course_id"_t2) |
       // GROUP BY c.course_id, c.title
       group_by("course_id"_t1, "title"_t1) |
       // Collect the result rows into a std::vector<CourseStatsView>
       to<std::vector<CourseStatsView>>{})(
          conn);

  if (!query_res) {
    // On query error, return empty vector
    return {};
  }

  // 4. Convert CourseStatsView results into CourseStats.
  std::vector<CourseStats> stats;
  stats.reserve(query_res->size());

  for (const auto& row : *query_res) {
    CourseStats cs;
    cs.title = row.title;
    cs.student_count = row.student_count;
    cs.avg_grade = row.avg_grade;
    stats.push_back(std::move(cs));
  }

  return stats;
}

}  // namespace query_course_enrollment_stats
