  std::string product_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};


/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::literals;

  // 1. Connect to SQLite database "test_db.sqlite"
  auto conn_res = connect("test_db.sqlite");

  // 2. Create tables (if not exist)
  conn_res = create_table<Customer>{.if_not_exists_ = true}(conn_res)
                 .and_then(
                     create_table<Order>{.if_not_exists_ = true})
                 .and_then(
                     create_table<Product>{.if_not_exists_ = true})
                 .and_then(
                     create_table<OrderItem>{.if_not_exists_ = true});

  // If connection or table creation failed, return empty vector.
  if (!conn_res) {
    return {};
  }

  auto& conn = *conn_res;

  // Aliased column literals
  constexpr auto c  = "Customer"_t1;
  constexpr auto o  = "Order"_t2;
  constexpr auto oi = "OrderItem"_t3;
  constexpr auto p  = "Product"_t4;

  // 3. Build the query:
  // SELECT p.name, o.order_date, oi.quantity
  // FROM Customer c
  // JOIN "Order" o ON c.customer_id = o.customer_id
  // JOIN OrderItem oi ON o.order_id = oi.order_id
  // JOIN Product p ON oi.product_id = p.product_id
  // WHERE c.customer_id = ?
  // ORDER BY o.order_date DESC;
  //
  // We use sqlgen's select_from / join / where / order_by API and map into
  // PurchaseHistory via to<PurchaseHistory>.
  //
  // Note: sqlgen handles mapping from the selected columns into the struct
  // fields in order of declaration.

  auto query =
      select_from<Customer, "t1">(p("name"), o("order_date"), oi("quantity")) |
      inner_join<Order, "t2">(c("customer_id") == o("customer_id")) |
      inner_join<OrderItem, "t3">(o("order_id") == oi("order_id")) |
      inner_join<Product, "t4">(oi("product_id") == p("product_id")) |
      where(c("customer_id") == customer_id) |
      order_by(desc(o("order_date"))) |
      to<std::vector<PurchaseHistory>>;

  auto res = query(conn);

  if (!res) {
    return {};
  }

  return *res;
}

}  // namespace query_customer_purchase_history
