namespace query_daily_traffic_metrics {

struct PageVisit {
  sqlgen::PrimaryKey<int> visit_id;
  std::string url;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> visit_time;
};

struct DailyTraffic {
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

struct DailyTrafficView {
  static constexpr const char* tablename = "DailyTrafficView";
  static constexpr bool is_view = true;
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");

  // Build a query equivalent to:
  // SELECT strftime('%Y-%m-%d', visit_time) AS visit_date,
  //        COUNT(*) AS total_visits,
  //        COUNT(DISTINCT url) AS unique_pages
  // FROM PageVisit
  // GROUP BY visit_date
  // ORDER BY visit_date;
  //
  // We use select_from<PageVisit> with:
  //   - the raw strftime expression, aliased as "visit_date"
  //   - count() aliased as "total_visits"
  //   - count_distinct("url"_c) aliased as "unique_pages"
  // and map the result into DailyTrafficView, then into DailyTraffic.
  auto query =
      select_from<PageVisit>(
          as<"visit_date">("strftime('%Y-%m-%d', visit_time)"),
          as<"total_visits">(count()),
          as<"unique_pages">(count_distinct("url"_c)))
      | group_by("visit_date"_c)
      | order_by("visit_date"_c)
      | to<std::vector<DailyTrafficView>>;

  auto res = query(conn_res);

  std::vector<DailyTraffic> result;

  if (!res) {
    // On error, return an empty vector; in a real system you might propagate
    // or log res.error().
    return result;
  }

  const auto& rows = *res;
  result.reserve(rows.size());
  for (const auto& r : rows) {
    result.push_back(DailyTraffic{
        .visit_date = r.visit_date,
        .total_visits = r.total_visits,
        .unique_pages = r.unique_pages,
    });
  }

  return result;
}

}  // namespace query_daily_traffic_metrics
