  /// Returns an IN condition.
  template <class... Ts>
  auto in(const Ts&... _ts) const noexcept {
    return transpilation::make_condition(transpilation::conditions::in(
        transpilation::Col<_name, _alias>{}, _ts...));
  }

  /// Returns an IS NULL condition.
