std::vector<OrderView> query_high_value_orders() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");

  // Build the query:
  // SELECT o.order_id, c.name, o.total_amount, o.order_date
  // FROM "Order" o
  // INNER JOIN Customer c ON o.customer_id = c.customer_id
  // WHERE o.total_amount > 1000
  // ORDER BY o.total_amount DESC;
  auto query =
      select_from<Order, "o">(col<"order_id", "o">(), col<"name", "c">(),
                              col<"total_amount", "o">(),
                              col<"order_date", "o">()) |
      inner_join<Customer, "c">(col<"customer_id", "o">() ==
                                col<"customer_id", "c">()) |
      where(col<"total_amount", "o">() > 1000) |
      order_by(col<"total_amount", "o">().desc()) |
      to<std::vector<OrderView>>;

  auto res = query(conn_res);

  // On error, return an empty vector (could also throw/propagate instead).
  if (!res) {
    return {};
  }

  return *res;
}

}  // namespace query_high_value_orders
