  static constexpr const char* tablename = "ProductSalesReport";
  static constexpr bool is_view = true;
  std::string category;
  int total_qty;
  double total_amt;
};

std::vector<CategoryReport> query_product_sales_report() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");

  // Build query equivalent to:
  // SELECT p.category, SUM(s.quantity) AS total_qty, SUM(s.amount) AS total_amt
  // FROM Product p
  // INNER JOIN Sale s ON p.product_id = s.product_id
  // GROUP BY p.category
  // HAVING total_amt > 5000;
  //
  // Implemented as a view-like query to ProductSalesReport and then read it.
  auto query =
      select_from<ProductSalesReport, "psr"_t1>("category"_t1, "total_qty"_t1,
                                                "total_amt"_t1);

  // Execute query and collect results into std::vector<CategoryReport>
  // We map fields positionally: category, total_qty, total_amt.
  auto res = conn_res.and_then([&](auto& conn) {
    return query(&conn).and_then(
        [](auto range) -> sqlgen::Result<std::vector<CategoryReport>> {
          std::vector<CategoryReport> out;
          for (auto& row_res : range) {
            if (!row_res) {
              return sqlgen::error(row_res.error().what());
            }
            auto nt = *row_res;
            CategoryReport cr;
            cr.category = rfl::get<0>(nt);
            cr.total_qty = rfl::get<1>(nt);
            cr.total_amt = rfl::get<2>(nt);
            out.emplace_back(std::move(cr));
          }
          return out;
        });
  });

  // On error, return empty vector; otherwise return the data.
  if (!res) {
    return {};
  }
  return *res;
}

}  // namespace query_product_sales_report
