namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 *
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");

  // Build up an optional WHERE condition dynamically.
  // We'll keep track of whether we already have a condition and combine with &&
  // as needed.
  std::optional<transpilation::Condition<typename decltype("book_id"_c ==
                                                           0)::ConditionType>>
      where_cond;

  // Helper lambda to append a new condition with logical AND.
  auto add_cond = [&where_cond](auto new_cond) {
    using NewCondType = decltype(new_cond.condition);
    if (!where_cond.has_value()) {
      where_cond = new_cond;
    } else {
      where_cond = (*where_cond && new_cond);
    }
  };

  // Title keyword -> title LIKE '%keyword%'
  if (filters.title_keyword.has_value()) {
    std::string pattern = "%" + *filters.title_keyword + "%";
    add_cond("title"_c.like(pattern));
  }

  // Minimum year -> year >= min_year
  if (filters.min_year.has_value()) {
    add_cond("year"_c >= *filters.min_year);
  }

  // Genre equality -> genre = ?
  if (filters.genre.has_value()) {
    add_cond("genre"_c == *filters.genre);
  }

  // Maximum price -> price <= max_price
  if (filters.max_price.has_value()) {
    add_cond("price"_c <= *filters.max_price);
  }

  // Start with a base read of Book
  auto query = read<std::vector<Book>>;

  // Attach WHERE if any condition was created
  if (where_cond.has_value()) {
    query = query | where(where_cond->condition);
  }

  // Execute the query
  auto result = query(conn_res);

  // Unwrap the sqlgen::Result<std::vector<Book>> safely
  if (result) {
    return *result;
  }

  // On error, return an empty vector (could also throw/propagate error depending on design)
  return {};
}

}  // namespace query_search_books_by_criteria
