#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <sqlgen/exec.hpp>

namespace schema_migration_add_column {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * 
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");

  // If connection failed, return false
  if (!conn_res) {
    return false;
  }

  // Wrap connection in sqlgen::Ref (the connection type from the library
  // already returns a Result<Ref<Connection>> from Connection::make).
  auto conn_ref = *conn_res;

  // First ALTER TABLE: add phone_number column
  auto res = sqlgen::exec(conn_ref,
                          "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);");

  // If the first ALTER fails, we still want to allow "column already exists"
  // as a non-fatal error. SQLite uses error code 1 (SQL error) with a message
  // containing "duplicate column name" in this case. The sqlgen Result only
  // exposes a string error message, so we check the message text.
  if (!res) {
    const auto& err = res.error();
    if (err.msg().find("duplicate column name") == std::string::npos &&
        err.msg().find("already exists") == std::string::npos) {
      // Some other error -> abort migration.
      return false;
    }
    // Otherwise, ignore and continue to the next ALTER.
    res = sqlgen::Result<sqlgen::Ref<std::remove_reference_t<decltype(*conn_ref)>>>(
        conn_ref);
  }

  // Second ALTER TABLE: add is_active column with default 1 (true)
  auto res2 = sqlgen::exec(res,
                           "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;");

  if (!res2) {
    const auto& err = res2.error();
    if (err.msg().find("duplicate column name") == std::string::npos &&
        err.msg().find("already exists") == std::string::npos) {
      // Some other error -> abort migration.
      return false;
    }
  }

  // If we get here, both columns were added or already existed.
  return true;
}

} // namespace schema_migration_add_column
