namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

// Reflect the Document struct so sqlgen can map it to a table.
RFL_REFLECT(soft_delete_records::Document, doc_id, title, is_deleted,
            deleted_at);

bool soft_delete_records(const std::vector<int>& ids) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  if (ids.empty()) {
    // Nothing to delete; consider this a success.
    return true;
  }

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = *conn_res;

  // Start a transaction to ensure atomicity.
  auto tx_res = conn->transaction();
  if (!tx_res) {
    return false;
  }
  auto tx = *tx_res;

  // Build the UPDATE statement:
  // UPDATE Document
  // SET is_deleted = 1, deleted_at = CURRENT_TIMESTAMP
  // WHERE doc_id IN (ids...);
  //
  // We use:
  //   update<Document>( ...)
  //     | where("doc_id"_c.in(ids));
  //
  // "CURRENT_TIMESTAMP"_c is understood by sqlgen as the SQL function name,
  // so sqlite will evaluate it on execution.
  auto update_stmt =
      update<Document>("is_deleted"_c.set(1),
                       "deleted_at"_c.set("CURRENT_TIMESTAMP"_c)) |
      where("doc_id"_c.in(ids));

  // Execute the update within the transaction.
  auto exec_res = update_stmt(tx);
  if (!exec_res) {
    // If update failed, rollback and report failure.
    tx->rollback();
    return false;
  }

  // Commit the transaction.
  auto commit_res = tx->commit();
  if (!commit_res) {
    return false;
  }

  return true;
}

}  // namespace soft_delete_records
