template <class T>
class Iterator {
 public:
  using difference_type = std::ptrdiff_t;
  using value_type = Result<T>;

  struct End {
    bool operator==(const Iterator<T>& _it) const noexcept {
      return _it == *this;
    }

    bool operator!=(const Iterator<T>& _it) const noexcept {
      return _it != *this;
    }
  };

  Iterator(const Ref<IteratorBase>& _it)
      : current_batch_(get_next_batch(_it)), it_(_it), ix_(0) {}

