#pragma once

#include <filesystem>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

#include "eas_common.hpp"

namespace update_eas_table {

void update_eas_table() {
  // Ensure the initial schema (including Major) exists.
  design_eas_database_with_major();

  // Connect to the database.
  auto conn_res = sqlgen::sqlite::connect(db_path);
  auto& conn = conn_res.value();

  // 1. Add a new column `Grade` to the table `Score`, char(1), NOT NULL.
  //    SQLite: ALTER TABLE Score ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'F';
  //    We provide a DEFAULT so existing rows can satisfy NOT NULL.
  sqlgen::exec(conn,
               "ALTER TABLE Score "
               "ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'F';")
      .value();

  // 2. Modify the column type of `Age` in the table `Student` to `int`,
  //    allowing NULL values.
  //
  //    SQLite has limited ALTER TABLE support and cannot directly change a
  //    column type, so the standard pattern is:
  //      - create a new table with the desired schema
  //      - copy data
  //      - drop old table
  //      - rename new table
  //
  //    The original problem statement lists Student(SNo, Name, Sex, Birthday,
  //    Major, Scores, Remark, Age). The struct Student used by sqlgen does
  //    not contain Age, so we do the change with a raw SQL sequence that
  //    preserves an `Age` column, but makes it INTEGER NULL.
  //
  //    Note: The exact original column list/order is not enforced by the
  //    given sqlgen model, so we operate directly on the database schema.
  sqlgen::exec(conn, "PRAGMA foreign_keys = OFF;").value();

  // Create a new Student table with Age as INTEGER NULL.
  // We keep the rest of the columns compatible with the original description.
  sqlgen::exec(
      conn,
      "CREATE TABLE Student_new ("
      "  SNo    VARCHAR(10) PRIMARY KEY,"
      "  Name   VARCHAR(30) NOT NULL,"
      "  Sex    INTEGER NOT NULL,"
      "  Birthday DATETIME,"
      "  Major  INTEGER,"
      "  Scores REAL,"
      "  Remark TEXT,"
      "  Age    INTEGER"
      ");")
      .value();

  // Copy over all existing data; Age will be copied when present, otherwise
  // will be NULL.
  sqlgen::exec(
      conn,
      "INSERT INTO Student_new (SNo, Name, Sex, Birthday, Major, Scores, "
      "Remark, Age) "
      "SELECT SNo, Name, Sex, Birthday, Major, Scores, Remark, Age "
      "FROM Student;")
      .value();

  // Drop old Student and rename the new one.
  sqlgen::exec(conn, "DROP TABLE Student;").value();
  sqlgen::exec(conn, "ALTER TABLE Student_new RENAME TO Student;").value();

  sqlgen::exec(conn, "PRAGMA foreign_keys = ON;").value();

  // 3. Drop the table `Major`.
  //    Use sqlgen's drop<> helper with IF EXISTS semantics.
  sqlgen::drop<Major>
      .operator()(conn_res)  // start from the existing connection Result
      .value();
}

} // namespace update_eas_table
