  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  // Mark this struct as a VIEW for sqlgen
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");

  if (!conn_res) {
    return false;
  }

  auto conn = *conn_res;

  // Manually drop the view if it already exists (SQLite doesn't have
  // CREATE OR REPLACE VIEW in older versions, and sqlgen's create_as
  // does not emit "IF NOT EXISTS" for views by default).
  {
    auto drop_res =
        conn->execute("DROP VIEW IF EXISTS SalesSummary;");
    if (!drop_res) {
      return false;
    }
  }

  // Build the SELECT query for the view:
  //
  // SELECT p.name as product_name,
  //        SUM(s.quantity) as total_quantity,
  //        SUM(s.amount)   as total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name;
  //
  // using sqlgen's DSL.

  // Columns with table aliases:
  // p.name
  constexpr auto p_name = "name"_t1;
  // s.quantity, s.amount
  constexpr auto s_quantity = "quantity"_t2;
  constexpr auto s_amount   = "amount"_t2;

  auto select_query =
      select_from<Sale, "t2">(
          // p.name AS product_name
          p_name | as<"product_name">,
          // SUM(s.quantity) AS total_quantity
          sum(s_quantity) | as<"total_quantity">,
          // SUM(s.amount) AS total_revenue
          sum(s_amount) | as<"total_revenue">)
      // INNER JOIN Product p (alias t1) ON s.product_id = p.product_id
      | inner_join<Product, "t1">("product_id"_t2 == "product_id"_t1)
      // GROUP BY p.name
      | group_by(p_name);

  // Create the view from the SELECT query.
  // We already dropped it above, so a plain create_as is sufficient.
  auto create_res = create_as<SalesSummary>(select_query)(conn);

  return static_cast<bool>(create_res);
}

}  // namespace schema_create_view_sales_summary
