#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = sqlite::connect("test_db.sqlite");

  // We want all departments, even those without projects.
  // Since sqlgen provides a right_join helper, we can express:
  //
  //   SELECT d.name AS department_name, p.name AS project_name
  //   FROM Project p
  //   RIGHT JOIN Department d ON p.department_id = d.department_id;
  //
  // The result type is DepProj, with department_name optional to reflect
  // potential NULLs in the join (schema or data permitting).

  // Build a read query that selects into DepProj while using a RIGHT JOIN.
  auto query =
      read<std::vector<DepProj>>(
          // Select expressions in the same order as DepProj fields:
          // department_name, project_name.
          //
          // We alias the tables as t1 (Project) and t2 (Department).
          //
          // department_name  <- Department.name (aliased to "department_name")
          // project_name     <- Project.name   (aliased to "project_name")
          "name"_t2.as<"department_name">(),
          "name"_t1.as<"project_name">()) |
      // FROM Project AS t1
      from<Project>("t1") |
      // RIGHT JOIN Department AS t2 ON t1.department_id = t2.department_id
      right_join<Department, "t2">("department_id"_t1 ==
                                   "department_id"_t2);

  // Execute the query.
  auto res = query(conn_res);

  // Convert the sqlgen::Result<std::vector<DepProj>> into a plain vector.
  if (!res) {
    // In a real system you might throw, log, or propagate the error.
    // For this example we simply return an empty vector on failure.
    return {};
  }

  return *res;
}

}  // namespace right_join_departments_projects
