  std::string name;
};

struct B {
  sqlgen::PrimaryKey<int> id;
  int a_id;
  double score;
};

/**
 * This function demonstrates how to build a conditional SQL query.
 * It joins tables A and B, filtering for records where score > 10 and name contains 'x'.
 * Returns: std::string.
 */
std::string generate_sql_dry_run() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database "test_db.sqlite" (connection is not used to execute,
  // but demonstrates how you'd normally obtain one; this is effectively a dry run).
  auto conn = sqlite::connect("test_db.sqlite");

  // Build a complex query:
  // SELECT t1.id, t1.name, t2.score
  // FROM A AS t1
  // INNER JOIN B AS t2 ON t1.id = t2.a_id
  // WHERE t2.score > 10 AND t1.name LIKE '%x%'
  // ORDER BY t2.score DESC
  // LIMIT 5;
  //
  // Note: We use the column literal helpers with table aliases (_t1, _t2).
  auto query =
      select_from<A, "t1">("id"_t1, "name"_t1, "score"_t2) |
      inner_join<B, "t2">("id"_t1 == "a_id"_t2) |
      where(("score"_t2 > 10.0) && ("name"_t1.like("%x%"))) |
      order_by(-"score"_t2) |  // minus sign means DESC in sqlgen
      limit(5);

  // Generate SQL string for SQLite (dry run, no execution).
  std::string sql = sqlite::to_sql(query);

  // Basic verification that the generated SQL contains the expected clauses.
  // These checks are not exhaustive, but help ensure the structure is correct.
  assert(sql.find("SELECT") != std::string::npos);
  assert(sql.find("FROM") != std::string::npos);
  assert(sql.find("JOIN") != std::string::npos);
  assert(sql.find("WHERE") != std::string::npos);
  assert(sql.find("ORDER BY") != std::string::npos);
  assert(sql.find("LIMIT") != std::string::npos);

  // More specific checks related to our query intent.
  assert(sql.find("A") != std::string::npos || sql.find("a") != std::string::npos);
  assert(sql.find("B") != std::string::npos || sql.find("b") != std::string::npos);
  assert(sql.find("score") != std::string::npos);
  assert(sql.find("name") != std::string::npos);

  // Print the SQL for debugging purposes (dry run output).
  std::cout << "Generated SQL (dry run): " << sql << '\n';

  // Return the generated SQL string.
  return sql;
}

}  // namespace generate_sql_dry_run
