#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>
#include <string>
#include <cstdint>

namespace analyze_temporal_data {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string event_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

/**
 * @brief Analyze temporal data for a collection of events.
 *
 * Inserts the provided events into a SQLite database "test_db.sqlite",
 * creates the Event table if needed, runs a query to extract date/time
 * parts and compute duration, and returns the results as a vector of
 * TemporalAnalysis.
 *
 * @param events Vector of Event records to analyze.
 * @return std::vector<TemporalAnalysis> Analysis results for each event that has an end_time.
 */
std::vector<TemporalAnalysis> analyze_temporal_data(const std::vector<Event>& events) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return {};
  }
  auto conn = *conn_res;

  // Ensure Event table exists (schema as specified)
  {
    const char* create_sql =
        "CREATE TABLE IF NOT EXISTS Event ("
        "  event_id   INTEGER PRIMARY KEY,"
        "  event_name TEXT NOT NULL,"
        "  start_time TEXT NOT NULL,"
        "  end_time   TEXT,"
        "  created_at TEXT NOT NULL"
        ");";
    auto res = conn->execute(create_sql);
    if (!res) {
      return {};
    }
  }

  // Insert provided events (upsert semantics on primary key to keep example simple)
  {
    const char* insert_sql =
        "INSERT OR REPLACE INTO Event (event_id, event_name, start_time, end_time, created_at) "
        "VALUES (?1, ?2, ?3, ?4, ?5);";

    for (const auto& e : events) {
      auto stmt_res = conn->prepare(insert_sql);
      if (!stmt_res) {
        return {};
      }
      auto stmt = *stmt_res;

      // Bind parameters in the same order as the INSERT statement
      // sqlgen::Timestamp<...> can be bound as its string representation
      stmt.bind(1, static_cast<int>(e.event_id));
      stmt.bind(2, e.event_name);
      stmt.bind(3, e.start_time.to_string());

      if (e.end_time.has_value()) {
        stmt.bind(4, e.end_time->to_string());
      } else {
        stmt.bind_null(4);
      }

      stmt.bind(5, e.created_at.to_string());

      auto exec_res = stmt.execute();
      if (!exec_res) {
        return {};
      }
    }
  }

  // Define a lightweight struct that matches the temporal analysis projection.
  // This is what sqlgen will materialize directly from the SELECT.
  struct DbTemporalAnalysis {
    int event_id;
    std::string event_name;
    int start_day;
    int start_month;
    int start_year;
    int start_hour;
    int start_minute;
    int start_second;
    int start_weekday;
    int64_t start_epoch;
    std::optional<double> duration_days;
  };

  // Build the query using sqlgen operations and select_from.
  // This mirrors the reference SQL:
  //
  // SELECT
  //   event_id,
  //   event_name,
  //   DAY(start_time)        AS start_day,
  //   MONTH(start_time)      AS start_month,
  //   YEAR(start_time)       AS start_year,
  //   HOUR(start_time)       AS start_hour,
  //   MINUTE(start_time)     AS start_minute,
  //   SECOND(start_time)     AS start_second,
  //   WEEKDAY(start_time)    AS start_weekday,
  //   UNIXEPOCH(start_time)  AS start_epoch,
  //   DAYS_BETWEEN(start_time, end_time) AS duration_days
  // FROM Event
  // WHERE end_time IS NOT NULL;

  auto query =
      select_from<Event>(
          "event_id"_c,
          "event_name"_c,
          day("start_time"_c),
          month("start_time"_c),
          year("start_time"_c),
          hour("start_time"_c),
          minute("start_time"_c),
          second("start_time"_c),
          weekday("start_time"_c),
          unixepoch("start_time"_c),
          days_between("start_time"_c, "end_time"_c)) |
      where("end_time"_c.is_not_null()) |
      to<std::vector<DbTemporalAnalysis>>;

  auto res = query(conn);
  if (!res) {
    return {};
  }

  const auto& db_rows = *res;

  // Map DbTemporalAnalysis to the public TemporalAnalysis type.
  std::vector<TemporalAnalysis> out;
  out.reserve(db_rows.size());
  for (const auto& r : db_rows) {
    TemporalAnalysis ta{
        .event_id = r.event_id,
        .event_name = r.event_name,
        .start_day = r.start_day,
        .start_month = r.start_month,
        .start_year = r.start_year,
        .start_hour = r.start_hour,
        .start_minute = r.start_minute,
        .start_second = r.start_second,
        .start_weekday = r.start_weekday,
        .start_epoch = r.start_epoch,
        .duration_days = r.duration_days};
    out.emplace_back(std::move(ta));
  }

  return out;
}

}  // namespace analyze_temporal_data
