                                    ItBegin _begin, ItEnd _end,
                                    bool _or_replace) {
  using T =
      std::remove_cvref_t<typename std::iterator_traits<ItBegin>::value_type>;

  const auto insert_stmt =
      transpilation::to_insert_or_write<T, dynamic::Insert>(_or_replace);

