/**
 * description: upsert_inventory_items.
 * This function demonstrates how to use upsert (insert or replace) statements in sqlgen write API.
 * It inserts or replaces the given inventory items in the Inventory table.
 *
 * Returns true if:
 *   - the upsert operation succeeds, and
 *   - reading the items back from the database succeeds.
 */
bool upsert_inventory_items(const std::vector<Inventory>& items) {
  using namespace sqlgen;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = *conn_res;

  // 1. Ensure the Inventory table exists.
  //    write(...) will create the table if it does not exist and insert data.
  //    We can pass an empty container here just to trigger table creation
  //    without inserting any rows.
  std::vector<Inventory> empty_items;
  auto write_res = write(conn, empty_items);
  if (!write_res) {
    return false;
  }

  // 2. Perform insert-or-replace (upsert) for the provided items.
  auto upsert_res = insert_or_replace(conn, items);
  if (!upsert_res) {
    return false;
  }

  // 3. Read back all inventory items to verify the upsert behavior.
  //    If the read fails, return false; otherwise, return true.
  auto read_res = read<std::vector<Inventory>> (conn);
  if (!read_res) {
    return false;
  }

  // Optionally, callers could inspect *read_res to verify contents.
  // For this function, success of the read is considered verification.
  return true;
}

}  // namespace upsert_inventory_items
