namespace analyze_social_network {

// -----------------------------------------------------------------------------
// Data structures used by sqlgen for the actual DB tables
// -----------------------------------------------------------------------------

struct DbUser {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::string email;
  std::string join_date;  // stored as TEXT/datetime
  std::optional<std::string> city;
};

struct DbFriendship {
  int user_id1;
  int user_id2;
  std::string friendship_date;  // stored as TEXT/datetime
};

// -----------------------------------------------------------------------------
// Structures provided by the caller
// -----------------------------------------------------------------------------

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

// Internal struct used to collect query results
struct FriendConnectionRow {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze social network data by creating SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 *
 * This function:
 *  1. Connects to "test_db.sqlite".
 *  2. Creates User and Friendship tables (if they don't exist).
 *  3. Inserts provided users and friendships.
 *  4. Performs several analyses (mutual friends, friend-of-friend, etc.).
 *  5. Returns mutual friend pairs (as FriendConnection).
 */
std::vector<FriendConnection> analyze_social_network_impl(
    const std::vector<User>& users,
    const std::vector<Friendship>& friendships) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // 1. Connect to SQLite database
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return {};
  }
  auto conn = *conn_res;

  // 2. Create tables for DbUser and DbFriendship
  auto res =
      create_table<DbUser>(conn, /*if_not_exists=*/true)
          .and_then(create_table<DbFriendship>(std::placeholders::_1,
                                               /*if_not_exists=*/true));

  if (!res) {
    return {};
  }

  // 3. Insert provided users
  for (const auto& u : users) {
    DbUser dbu{
        .user_id = u.user_id,
        .username = u.username,
        .email = u.username + "@example.com",
        .join_date = "2024-01-01 00:00:00",
        .city = std::optional<std::string>{"Unknown"},
    };
    auto ins_res = conn->insert(dbu);
    if (!ins_res) {
      // ignore duplicate / constraint errors for simplicity
    }
  }

  // Insert provided friendships (store undirected as two rows for ease of join)
  for (const auto& f : friendships) {
    DbFriendship f1{
        .user_id1 = f.user1_id,
        .user_id2 = f.user2_id,
        .friendship_date = f.created_at.to_string(),
    };
    DbFriendship f2{
        .user_id1 = f.user2_id,
        .user_id2 = f.user1_id,
        .friendship_date = f.created_at.to_string(),
    };

    auto ins1 = conn->insert(f1);
    if (!ins1) {
      // ignore errors
