#include <vector>
#include <string>

namespace mathematical_operations_analysis {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int quantity;
  double discount_rate;
};

struct MathAnalysis {
  int product_id;
  std::string name;
  double abs_price;
  double ceil_price;
  double floor_price;
  double rounded_price;
  double exp_discount;
  double ln_price;
  double log2_quantity;
  double sin_discount;
  double cos_discount;
  double tan_discount;
  double sqrt_quantity;
};

/**
 * Insert products into a temporary SQLite table and run a SELECT that computes
 * various mathematical expressions, returning results as std::vector<MathAnalysis>.
 */
std::vector<MathAnalysis> analyze_mathematical_operations(const std::vector<Product>& products) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the provided SQLite database file.
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // In case of connection failure, return empty result.
    return {};
  }
  auto conn = *conn_res;

  // Ensure the Product table exists with the expected schema.
  {
    const char* create_sql =
        "CREATE TABLE IF NOT EXISTS Product ("
        "  product_id INTEGER PRIMARY KEY,"
        "  name TEXT NOT NULL,"
        "  price REAL NOT NULL,"
        "  quantity INTEGER NOT NULL,"
        "  discount_rate REAL NOT NULL"
        ");";
    auto res = conn->execute(create_sql);
    if (!res) {
      return {};
    }
  }

  // Clear any existing data to make this a self‑contained demonstration.
  {
    auto res = conn->execute("DELETE FROM Product;");
    if (!res) {
      return {};
    }
  }

  // Insert the provided products.
  {
    const char* insert_sql =
        "INSERT INTO Product (product_id, name, price, quantity, discount_rate) "
        "VALUES (?1, ?2, ?3, ?4, ?5);";
    auto stmt_res = conn->prepare(insert_sql);
    if (!stmt_res) {
      return {};
    }
    auto stmt = *stmt_res;

    for (const auto& p : products) {
      stmt->reset();
      stmt->bind(1, static_cast<int>(p.product_id));
      stmt->bind(2, p.name);
      stmt->bind(3, p.price);
      stmt->bind(4, p.quantity);
      stmt->bind(5, p.discount_rate);
      auto exec_res = stmt->step();
      if (!exec_res) {
        return {};
      }
    }
  }

  // Define a minimal reflection-compatible struct for reading the computed columns.
  struct Row {
    int product_id;
    std::string name;
    double abs_price;
    double ceil_price;
    double floor_price;
    double rounded_price;
    double exp_discount;
    double ln_price;
    double log2_quantity;
    double sin_discount;
    double cos_discount;
    double tan_discount;
    double sqrt_quantity;
  };

  // Perform the mathematical analysis using sqlgen operations.
  auto range_res =
      select_from<Product>(
          "product_id"_c,
          "name"_c,
          abs("price"_c) | as<"abs_price">,
          ceil("price"_c) | as<"ceil_price">,
          floor("price"_c) | as<"floor_price">,
          round("price"_c, 2) | as<"rounded_price">,
          exp("discount_rate"_c / 100.0) | as<"exp_discount">,
          ln("price"_c) | as<"ln_price">,
          log2("quantity"_c) | as<"log2_quantity">,
          sin("discount_rate"_c) | as<"sin_discount">,
          cos("discount_rate"_c) | as<"cos_discount">,
          tan("discount_rate"_c) | as<"tan_discount">,
          sqrt("quantity"_c) | as<"sqrt_quantity">) |
      to<std::vector<Row>>()(conn);

  if (!range_res) {
    return {};
  }

  const auto& rows = *range_res;
  std::vector<MathAnalysis> result;
  result.reserve(rows.size());

  for (const auto& r : rows) {
    MathAnalysis m;
    m.product_id = r.product_id;
    m.name = r.name;
    m.abs_price = r.abs_price;
    m.ceil_price = r.ceil_price;
    m.floor_price = r.floor_price;
    m.rounded_price = r.rounded_price;
    m.exp_discount = r.exp_discount;
    m.ln_price = r.ln_price;
    m.log2_quantity = r.log2_quantity;
    m.sin_discount = r.sin_discount;
    m.cos_discount = r.cos_discount;
    m.tan_discount = r.tan_discount;
    m.sqrt_quantity = r.sqrt_quantity;
    result.emplace_back(std::move(m));
  }

  return result;
}

}  // namespace mathematical_operations_analysis
