#include <algorithm>

namespace sqlgen::internal::strings {

char to_lower(const char ch) {
  if (ch >= 'A' && ch <= 'Z') {
    return ch + ('a' - 'A');
  } else {
    return ch;
  }
}

std::string to_lower(const std::string& _str) {
