#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace trim_and_length_validation {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  std::string email;
};

struct ValidatedProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::string trimmed_name;
  std::string trimmed_email;
  int name_length;
  int email_length;
};

/**
 * description: trim_and_length_validation.
 * This function demonstrates how to trim whitespace from string columns and validate their lengths using sqlgen read API.
 * It returns a vector of ValidatedProfile structs, where each struct contains the user_id, trimmed_name, trimmed_email, name_length, and email_length.
 * Returns: std::vector<ValidatedProfile>.
 */
std::vector<ValidatedProfile> trim_and_length_validation() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

  // Define a local struct that represents the projection we want to read.
  struct RowView {
    sqlgen::PrimaryKey<int> user_id;
    std::string trimmed_name;
    std::string trimmed_email;
    int name_length;
    int email_length;
  };

  // Build a read expression for RowView that:
  //  - selects user_id as-is
  //  - applies ltrim, rtrim and trim (via SQL) to both name and email
  //  - computes the length of the fully trimmed versions
  const auto query =
      sqlgen::read<std::vector<RowView>> |
      sqlgen::select<RowView>({
          // user_id mapped directly
          "user_id"_c = "user_id"_c,
          // demonstrate ltrim, rtrim, and trim on the name column
          "trimmed_name"_c =
              trim(rtrim(ltrim("name"_c))),  // equivalent to full trim
          // demonstrate ltrim, rtrim, and trim on the email column
          "trimmed_email"_c =
              trim(rtrim(ltrim("email"_c))),  // equivalent to full trim
          // lengths of the fully trimmed fields
          "name_length"_c =
              length(trim(rtrim(ltrim("name"_c)))),
          "email_length"_c =
              length(trim(rtrim(ltrim("email"_c))))
      });

  // Execute the query.
  auto rows_result = query(conn_result);

  std::vector<ValidatedProfile> result;

  // If execution failed, just return an empty vector (caller can decide how to
  // handle absence of data; for this example we keep it simple).
  if (!rows_result) {
    return result;
  }

  auto rows = *rows_result;
  result.reserve(rows.size());

  for (auto& row : rows) {
    result.push_back(ValidatedProfile{
        .user_id = row.user_id,
        .trimmed_name = std::move(row.trimmed_name),
        .trimmed_email = std::move(row.trimmed_email),
        .name_length = row.name_length,
        .email_length = row.email_length,
    });
  }

  return result;
}

}  // namespace trim_and_length_validation
