namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  using sqlgen::sqlite::connect;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = connect("test_db.sqlite");
  if (!conn_res) {
    // If the connection fails, return an empty result.
    return {};
  }

  auto conn = *conn_res;

  // Load the OrderItem data into the DB using sqlgen::write, which will
  // create the table if it does not exist and insert all rows.
  const auto write_res = sqlgen::write(conn, items);
  if (!write_res) {
    // If writing fails, return an empty result.
    return {};
  }

  // Define a simple, plain struct that matches the SELECT list.
  struct Row {
    int item_id;
    int order_id;
    int product_id;
    double unit_price;
    int quantity;
    double discount_rate;
    double tax_rate;
    double gross_total;
    double discounted_total;
    double final_total;
    double unit_cost;
    int quantity_group;
    double estimated_profit;
  };

  using sqlgen::literals::operator""_c;

  // Build a SELECT statement using sqlgen's column and operation abstractions.
  // This mirrors the reference SQL given in the prompt.
  //
  // COALESCE(discount_rate, 0) -> handled by SQLite itself; in C++ we still
  // reference discount_rate directly and use the SQL COALESCE() in the raw SQL
  // built by the library through literal values.
  //
  // The expression we want is:
  //  gross_total        = unit_price * quantity
  //  discounted_total   = gross_total * (1 - COALESCE(discount_rate, 0) / 100)
  //  final_total        = discounted_total * (1 + COALESCE(tax_rate, 0) / 100)
  //  unit_cost          = gross_total / quantity
  //  quantity_group     = quantity % 10
  //  estimated_profit   = unit_price * 0.3
  //
  // sqlgen provides arithmetic operators over Col and Operation, but not
  // a dedicated COALESCE helper, so we rely on the DB's COALESCE via
  // literal SQL in the connection. However, the given include set does not
  // expose a low-level expression builder for COALESCE, so we instead
  // replicate the *effect* by treating NULL as 0 via SQLite's inherent
  // behavior when multiplying/dividing by NULL in these metrics:
  //
  //   NULL / 100   -> NULL
  //   1 - NULL     -> NULL
  //   gross_total * NULL -> NULL
  //
  // To guarantee non-null numeric values in C++, we wrap the results by
  // selecting with the explicit COALESCE in the raw SQL string. The easiest,
  // fully supported path within the provided API surface is therefore to use
  // a plain SQL SELECT executed through Connection::read<Row>(), not the
  // high-level select_from builder.

  // Compose the SQL string that uses the full reference expression.
  const std::string sql =
      "SELECT "
      "  item_id, "
      "  order_id, "
      "  product_id, "
      "  unit_price, "
      "  quantity, "
      "  COALESCE(discount_rate, 0) AS discount_rate, "
      "  COALESCE(tax_rate, 0) AS tax_rate, "
      "  (unit_price * quantity) AS gross_total, "
      "  (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100.0)) AS discounted_total, "
      "  (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100.0) * "
      "     (1 + COALESCE(tax_rate, 0)/100.0)) AS final_total, "
      "  (unit_price * quantity / quantity) AS unit_cost, "
      "  (quantity % 10) AS quantity_group, "
      "  (unit_price * 0.3) AS estimated_profit "
      "FROM OrderItem";

  // Execute the query directly via the connection; the sqlgen::sqlite
  // Connection type exposes template read<Container>(sql_string).
  auto read_res = conn->template read<std::vector<Row>>(sql);
  if (!read_res) {
    return {};
  }

  const auto& rows = *read_res;
  std::vector<OrderMetrics> result;
  result.reserve(rows.size());

  for (const auto& r : rows) {
    OrderMetrics m;
    m.item_id = r.item_id;
    m.order_id = r.order_id;
    m.product_id = r.product_id;
    m.unit_price = r.unit_price;
    m.quantity = r.quantity;
    m.discount_rate = r.discount_rate;
    m.tax_rate = r.tax_rate;
    m.gross_total = r.gross_total;
    m.discounted_total = r.discounted_total;
    m.final_total = r.final_total;
    m.unit_cost = r.unit_cost;
    m.quantity_group = r.quantity_group;
    m.estimated_profit = r.estimated_profit;

    result.push_back(m);
  }

  return result;
}

}  // namespace calculate_order_metrics
