  sqlgen::PrimaryKey<int> note_id;
  std::string updated_content;
};

/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = connect("test_db.sqlite");

  // 1) Update: replace all occurrences of "foo" with "bar" in the Notes.content column.
  //    We use the sqlgen::replace operation to construct the expression:
  //      content = REPLACE(content, 'foo', 'bar')
  //
  //    Note: "content"_c uses the column-literal operator from sqlgen::literals.
  auto update_res =
      sqlgen::update<Note>("content"_c.set(sqlgen::replace("content"_c,
                                                           std::string("foo"),
                                                           std::string("bar"))))(
          conn_res);

  // If the update failed, just return an empty vector.
  if (!update_res) {
    return {};
  }

  // 2) Read back the updated values for verification.
  //    We select note_id and the (already updated) content column and
  //    map it into UpdatedNote.updated_content.
  auto read_res = sqlgen::read<std::vector<UpdatedNote>>( /* no where / limit */ )(
      update_res.value());

  if (!read_res) {
    return {};
  }

  return read_res.value();
}

}  // namespace replace_text_in_notes
