namespace inventory_bulk_write_and_read {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
  std::string location;
};

/**
 * description: inventory_bulk_write_and_read.
 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");

  // Drop and recreate the table to match the description
  // (even though the requirements say "assume Inventory table exists",
  //  the comment above the function explicitly states we should drop and recreate)
  conn_res = conn_res.and_then([](const auto& conn) {
    // Drop table if it exists
    const std::string drop_stmt = "DROP TABLE IF EXISTS Inventory;";
    return conn->execute(drop_stmt).transform([&](const auto&) { return conn; });
  });

  // Bulk write the provided inventory items (this will also CREATE TABLE for Inventory)
  conn_res = sqlgen::write(conn_res, items);

  // If any of the above steps failed, return false
  if (!conn_res) {
    return false;
  }

  // Read back items with quantity > 50 ordered by quantity descending.
  //
  // We use:
  //   where("quantity > 50")
  // and:
  //   order_by("quantity DESC")
  //
  // since sqlgen's string literal columns (`"quantity"_c`) do not carry
  // direction (ASC/DESC) information, and the provided library snippets
  // do not expose an explicit descending-order helper.
  //
  // The underlying transpiler accepts raw SQL fragments as ordering keys.
  auto read_res = (read<std::vector<Inventory>> |
                   where("quantity > 50") |
                   order_by("quantity DESC"))(conn_res);

  if (!read_res) {
    return false;
  }

  const auto& result_vec = *read_res;
  return !result_vec.empty();
}

}  // namespace inventory_bulk_write_and_read
