```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  // Enable ON DELETE CASCADE using the cascade helper
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::literals;

  // Connect to the SQLite database file.
  auto conn_res = connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.value();

  // Ensure foreign keys are enforced in SQLite.
  if (!conn->execute("PRAGMA foreign_keys = ON;")) {
    return false;
  }

  // Create Parent and Child tables with appropriate constraints.
  // Note: sqlgen infers constraints from PrimaryKey / ForeignKey types.
  if (!create_table<Parent>(conn).if_not_exists_(true)(conn)) {
    return false;
  }

  if (!create_table<Child>(conn).if_not_exists_(true)(conn)) {
    return false;
  }

  // Insert a parent row.
  Parent p{.parent_id = 1, .name = "parent"};
  if (!insert(p)(conn)) {
    return false;
  }

  // Insert a child row that references the parent.
  Child c{.child_id = 1, .parent_id = 1, .note = "child"};
  if (!insert(c)(conn)) {
    return false;
  }

  // Delete the parent row.
  auto parent_id_col = "parent_id"_c;
  if (!delete_from<Parent>() | where(parent_id_col == 1)(conn)) {
    return false;
  }

  // Verify whether child rows with that parent_id were deleted.
  // We simply try to select any remaining child rows with parent_id = 1.
  auto child_parent_id_col = "parent_id"_c;

  auto res = conn->to_vec<Child>(
      conn->to_sql(select<Child>() | where(child_parent_id_col == 1)));

  if (!res) {
    return false;
  }

  // If no child rows remain, cascade delete worked.
  return res.value().empty();
}

}  // namespace cascade_delete_demo
