/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite file database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }

  // Create Account table (if it does not already exist)
  auto res =
      sqlgen::create_table<Account>.if_not_exists_(true)(conn_res);
  if (!res) {
    return false;
  }

  // Insert some sample accounts
  std::vector<Account> accounts{
      Account{sqlgen::PrimaryKey<int>{1}, 100.0, "active"},
      Account{sqlgen::PrimaryKey<int>{2}, 200.0, "inactive"},
      Account{sqlgen::PrimaryKey<int>{3}, 300.0, "active"},
  };

  res = sqlgen::write(conn_res, accounts);
  if (!res) {
    return false;
  }

  // Use literals to reference columns
  constexpr auto account_id_c = "account_id"_c;
  constexpr auto balance_c = "balance"_c;
  constexpr auto status_c = "status"_c;

  // 1) Give a 50.0 bonus to all active accounts and set them to "preferred"
  res = sqlgen::update<Account>(
            balance_c.set(balance_c + 50.0),
            status_c.set("preferred")) |
        sqlgen::where(status_c == "active")(res);
  if (!res) {
    return false;
  }

  // 2) Zero out balance and mark "inactive" accounts as "closed"
  res = sqlgen::update<Account>(
            balance_c.set(0.0),
            status_c.set("closed")) |
        sqlgen::where(status_c == "inactive")(res);
  if (!res) {
    return false;
  }

  // Verify the changes persisted by selecting back the rows
  auto final_res = res.and_then([](const auto& c) {
    return c->template read_all<Account>();
  });
  if (!final_res) {
    return false;
  }

  const auto& final_accounts = *final_res;
  if (final_accounts.size() != 3) {
    return false;
  }

  // Expect:
  // id 1: 150.0, "preferred"
  // id 2: 0.0,   "closed"
  // id 3: 350.0, "preferred"
  bool ok = true;
  for (const auto& a : final_accounts) {
    if (a.account_id == 1) {
      if (a.balance != 150.0 || a.status != "preferred") ok = false;
    } else if (a.account_id == 2) {
      if (a.balance != 0.0 || a.status != "closed") ok = false;
    } else if (a.account_id == 3) {
      if (a.balance != 350.0 || a.status != "preferred") ok = false;
    } else {
      ok = false;
    }
  }

  return ok;
}

}  // namespace update_set_operations
