#include <optional>

namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a
 * supplier and the name of a product, if any.
 *
 * Demonstrates a FULL JOIN between Supplier and Product using sqlgen on a
 * SQLite database "test_db.sqlite".
 */
std::vector<SupProd> full_join_suppliers_products() {
  using namespace sqlgen;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = sqlite::connect("test_db.sqlite");

  // Build a FULL JOIN query between Supplier and Product.
  // Select supplier.name as supplier_name and product.name as product_name.
  auto query =
      select_from<Supplier>(
          col<"name">().as<"supplier_name">(),
          col<"name", "Product">().as<"product_name">()) |
      full_join<Product, "Product">(col<"supplier_id">() ==
                                    col<"supplier_id", "Product">()) |
      to<std::vector<SupProd>>;

  // Execute the query and extract the result or return an empty vector on error.
  auto res = query(conn_res);
  if (!res) {
    return {};
  }

  return *res;
}

}  // namespace full_join_suppliers_products
