 * It returns a vector of Book structs, where each struct contains the book_id, title, and pages.
 * Returns: std::vector<Book>, ordered by pages in descending order.
 */
std::vector<Book> select_from_read_to_vector() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite (in-memory for this example).
  auto conn_res = sqlite::connect();
  if (!conn_res) {
    return {};
  }
  auto conn = *conn_res;

  // Define the Book table for sqlgen.
  struct BookTable {
    PrimaryKey<int> book_id;
    std::string title;
    int pages;
  };

  // Ensure the table exists (schema creation is normally done elsewhere).
  conn->execute(
      "CREATE TABLE IF NOT EXISTS Book ("
      "book_id INTEGER PRIMARY KEY,"
      "title TEXT NOT NULL,"
      "pages INTEGER NOT NULL)");

  // Read all books ordered by pages in descending order into std::vector<Book>.
  auto res = select_from<BookTable>(
                 "book_id"_c, "title"_c, "pages"_c) |
             order_by("pages"_c.desc()) |
             to<std::vector<Book>> |
             conn;

  if (!res) {
    return {};
  }
  return *res;
}

}  // namespace select_from_read_to_vector
