#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees_impl
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts,
                                               const std::vector<Employee>& emps) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the provided SQLite database file.
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // On connection failure, just return an empty analysis.
    return {};
  }
  auto conn = *conn_res;

  // Recreate (or create) the tables to ensure they match the expected schema.
  // Department table
  auto res =
      exec(conn,
           "DROP TABLE IF EXISTS Department; "
           "DROP TABLE IF EXISTS Employee;");
  if (!res) {
    return {};
  }

  res = exec(
      res,
      "CREATE TABLE IF NOT EXISTS Department ("
      "  department_id   INTEGER PRIMARY KEY,"
      "  department_name VARCHAR(100) NOT NULL,"
      "  location        VARCHAR(100)"
      ");");
  if (!res) {
    return {};
  }

  // Employee table
  res = exec(
      res,
      "CREATE TABLE IF NOT EXISTS Employee ("
      "  employee_id   INTEGER PRIMARY KEY,"
      "  department_id INTEGER,"
      "  first_name    VARCHAR(50) NOT NULL,"
      "  last_name     VARCHAR(50) NOT NULL,"
      "  salary        REAL NOT NULL,"
      "  FOREIGN KEY(department_id) REFERENCES Department(department_id)"
      ");");
  if (!res) {
    return {};
  }

  // Insert Departments
  for (const auto& d : depts) {
    const auto sql =
        "INSERT INTO Department (department_id, department_name, location) "
        "VALUES (" +
        std::to_string(d.department_id.value()) + ", '" +
        d.department_name + "', '" + d.location + "');";
    res = exec(res, sql);
    if (!res) {
      return {};
    }
  }

  // Insert Employees
  for (const auto& e : emps) {
    const auto sql =
        "INSERT INTO Employee (employee_id, department_id, first_name, "
        "last_name, salary) "
        "VALUES (" +
        std::to_string(e.employee_id.value()) + ", " +
        std::to_string(e.department_id) + ", '" + e.first_name + "', '" +
        e.last_name + "', " + std::to_string(e.salary) + ");";
    res = exec(res, sql);
    if (!res) {
      return {};
    }
  }

  JoinAnalysis analysis;

  // Helper lambda to run a join query and map to std::vector<JoinResult>
  auto run_join_query = [&](const std::string& sql)
      -> std::vector<JoinResult> {
    std::vector<JoinResult> out;
    auto range_res = conn->template read<
        sqlgen::Range<sqlgen::Iterator<rfl::NamedTuple<
            std::optional<std::string>, std::optional<std::string>,
            std::optional<std::string>, std::optional<double>>>>>(sql);

    if (!range_res) {
      return out;
    }

    auto range = *range_res;
    for (auto it = range.begin(); it != typename decltype(range)::End(); ++it) {
      auto& row_res = *it;
      if (!row_res) {
        continue;
      }
      auto nt = *row_res;
      JoinResult jr;
      jr.department_name = rfl::get<0>(nt.values());
      jr.first_name = rfl::get<1>(nt.values());
      jr.last_name = rfl::get<2>(nt.values());
      jr.salary = rfl::get<3>(nt.values());
      out.emplace_back(std::move(jr));
    }
    return out;
  };

  // INNER JOIN: employees with assigned departments
  {
    // Using raw SQL to make the NULL-ability explicit via COALESCE in the
    // SELECT list (still mapped into optionals).
    std::string sql_inner =
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Department d "
        "INNER JOIN Employee e ON d.department_id = e.department_id;";
    analysis.inner_join_results = run_join_query(sql_inner);
  }

  // LEFT JOIN: all employees, even those without departments
  {
    std::string sql_left =
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Employee e "
        "LEFT JOIN Department d ON e.department_id = d.department_id;";
    analysis.left_join_results = run_join_query(sql_left);
  }

  // RIGHT JOIN: all departments, even those without employees.
  // SQLite doesn't support RIGHT JOIN directly, so emulate using LEFT JOIN
  // with reversed tables.
  {
    std::string sql_right =
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Department d "
        "LEFT JOIN Employee e ON d.department_id = e.department_id;";
    analysis.right_join_results = run_join_query(sql_right);
  }

  // FULL JOIN: all departments and all employees.
  // Emulate FULL OUTER JOIN using UNION of LEFT and RIGHT join emulations.
  {
    std::string sql_full =
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Department d "
        "LEFT JOIN Employee e ON d.department_id = e.department_id "
        "UNION "
        "SELECT d.department_name, e.first_name, e.last_name, e.salary "
        "FROM Employee e "
        "LEFT JOIN Department d ON e.department_id = d.department_id;";
    analysis.full_join_results = run_join_query(sql_full);
  }

  return analysis;
}

}  // namespace analyze_department_employees
