#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <unordered_map>

namespace update_inventory_stock {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int stock;
};

bool update_inventory_stock(const std::unordered_map<int, int>& received) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) return false;

  // Ensure the Product table exists (if_not_exists = true)
  auto create_res = create_table<Product>(conn_res);
  if (!create_res) return false;

  // Begin a transaction
  auto txn_res = begin_transaction(create_res.value());
  if (!txn_res) return false;
  auto txn = txn_res.value();

  // Perform all updates inside the transaction
  for (const auto& [pid, qty] : received) {
    // Use sqlgen::exec with a plain SQL string; quantity and id are ints so
    // direct interpolation here is safe from injection.
    std::string sql = "UPDATE Product "
                      "SET stock = stock + " +
                      std::to_string(qty) +
                      " WHERE product_id = " + std::to_string(pid) + ";";

    auto exec_res = exec(txn, sql);
    if (!exec_res) {
      // On failure, rely on transaction going out of scope without commit
      // (implicit rollback by the DB engine).
      return false;
    }
  }

  // Commit the transaction; return true only on success
  auto commit_res = commit(txn);
  return commit_res.has_value();
}

}  // namespace update_inventory_stock
