namespace create_view_order_summary {

using namespace sqlgen;
using namespace sqlgen::literals;

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* tablename = "OrderSummaryView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: This function demonstrates creating a view.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the SELECT that matches the reference SQL:
  //
  // SELECT o.order_id, o.customer, SUM(oi.unit_price*oi.quantity) as total
  // FROM Order o
  // INNER JOIN OrderItem oi ON o.order_id = oi.order_id
  // GROUP BY o.order_id, o.customer;
  //
  // Note:
  // - We alias the tables as t1 (Order) and t2 (OrderItem).
  // - The field aliases ("order_id", "customer", "total") must match
  //   the names in OrderSummary so that rfl/sqlgen can map them.

  // Columns for Order (alias t1) and OrderItem (alias t2)
  auto order_id_col     = "order_id"_t1();
  auto customer_col     = "customer"_t1();
  auto unit_price_col   = "unit_price"_t2();
  auto quantity_col     = "quantity"_t2();
  auto order_id_fk_col  = "order_id"_t2();

  // SUM(oi.unit_price * oi.quantity) AS total
  auto total_expr = sqlgen::sum(unit_price_col * quantity_col)
                        .as<"total">();

  // Build the select_from with join and group_by
  auto select_query =
      sqlgen::select_from<Order, "t1">(
          order_id_col.as<"order_id">(),
          customer_col.as<"customer">(),
          total_expr)
      | sqlgen::inner_join<OrderItem, "t2">(order_id_col == order_id_fk_col)
      | sqlgen::group_by(order_id_col, customer_col)
      | sqlgen::to<std::vector<OrderSummary>>();

  // Create or replace the view from the above query
  auto create_view_res =
      sqlgen::create_or_replace_view_as<OrderSummary>(select_query)(conn_res);

  // If creation failed, return empty vector
  if (!create_view_res) {
    return {};
  }

  // Read from the view to verify data
  auto read_res = sqlgen::read<std::vector<OrderSummary>>()(
      create_view_res.value());

  if (!read_res) {
    return {};
  }

  return read_res.value();
}

}  // namespace create_view_order_summary
