#include <sqlgen.hpp>
#include <sqlgen/literals.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace left_join_explicit {

struct User {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> id;
  int user_id;
  std::string title;
};

/**
 * This function demonstrates a LEFT JOIN.
 * Returns: std::string.
 */
inline std::string left_join_explicit() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Define the Product struct locally as requested.
  struct Product {
    sqlgen::PrimaryKey<int> id;
    std::string name;
  };

  // Build a query selecting products where name LIKE 'A%'.
  // We only need the SQL string, so we construct the query object
  // and transpile it with sqlite::to_sql.
  const auto query =
      select_from<Product>("id"_c, "name"_c) |
      where("name"_c.like("A%"));

  return sqlite::to_sql(query);
}

