namespace weekday_sales_analysis {

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> sale_time;
};

struct WeekdayStats {
  int weekday;
  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite".
  auto conn_res = connect("test_db.sqlite");

  // Build: SELECT weekday(sale_time) AS weekday,
  //               SUM(quantity)      AS total_quantity
  //        FROM Sales
  //        GROUP BY weekday(sale_time);
  //
  // We project into WeekdayStats directly via to<WeekdayStats>.
  auto query =
      select_from<Sales>(
          weekday("sale_time"_c) | as<"weekday">,
          sum("quantity"_c) | as<"total_quantity">) |
      group_by(weekday("sale_time"_c)) |
      to<std::vector<WeekdayStats>>;

  auto res = query(conn_res);

  if (!res) {
    // On error, return an empty vector (could also throw or log as needed).
    return {};
  }

  return *res;
}

}  // namespace weekday_sales_analysis
