namespace project_time_tracking {

using namespace sqlgen;
using namespace sqlgen::literals;

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  sqlgen::PrimaryKey<int> log_id;
  int project_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build and execute the query:
  // - Join Project and TimeLog
  // - Extract day/month/year/hour/minute/second from start_time
  // - Compute days_between(start_time, end_time) as duration_days
  // - Group by project and week (approximated here by year + week-number)
  //
  // Note: sqlgen provides weekday() and year(); we approximate "week"
  //       as integer division of day-of-year by 7 using unixepoch math.
  //
  // For clarity and portability, we group by:
  //   project_id, name, year(start_time),
  //   (unixepoch(start_time) / 604800)  -- 7 * 24 * 60 * 60 seconds
  //
  // and aggregate duration_days with SUM.
  //
  // However, the TimeMetrics struct is per-log, not per-aggregate-week.
  // To stay consistent with the requested return type, we:
  //   * still perform grouping on project + week
  //   * but compute component fields from MIN(start_time) in that week.
  //
  // If you want strictly per-log rows, just remove the group_by(...) and
  // SUM/MIN, and return one TimeMetrics per TimeLog instead.

  using sqlgen::day;
  using sqlgen::month;
  using sqlgen::year;
  using sqlgen::hour;
  using sqlgen::minute;
  using sqlgen::second;
  using sqlgen::days_between;
  using sqlgen::unixepoch;
  using sqlgen::group_by;

  // Aliased columns for expressions
  constexpr auto project_id_c = "project_id"_t1;
  constexpr auto name_c       = "name"_t1;
  constexpr auto start_c      = "start_time"_t2;
  constexpr auto end_c        = "end_time"_t2;

  // We will create a small intermediate struct matching the aggregation shape,
  // then map it into TimeMetrics (since TimeMetrics has no "week" field).
  struct AggregatedWeeklyMetrics {
    sqlgen::PrimaryKey<int> project_id;
    std::string name;
    int day;
    int month;
    int year;
    int hour;
    int minute;
    int second;
    double duration_days;
  };

  // Build query:
  // SELECT
  //   p.project_id,
  //   p.name,
  //   DAY(MIN(t.start_time))      AS day,
  //   MONTH(MIN(t.start_time))    AS month,
  //   YEAR(MIN(t.start_time))     AS year,
  //   HOUR(MIN(t.start_time))     AS hour,
  //   MINUTE(MIN(t.start_time))   AS minute,
  //   SECOND(MIN(t.start_time))   AS second,
  //   SUM(DAYS_BETWEEN(t.start_time, t.end_time)) AS duration_days
  // FROM Project p
  // JOIN TimeLog t ON p.project_id = t.project_id
  // GROUP BY
  //   p.project_id,
  //   p.name,
  //   YEAR(t.start_time),
  //   (UNIXEPOCH(t.start_time) / 604800);

  // To use MIN and SUM we rely on sqlgen's operations via "col()" + operators.
  // If aggregation helpers (sum, min) are not present in this snapshot, you
  // can still aggregate on the raw expressions and perform grouping entirely
  // in SQLite via raw SQL; but here we stay with the fluent API as requested.

  // sqlgen's current header excerpt does not show sum()/min(), so we will do
  // the simpler variant: *no aggregation*, one row per TimeLog, while still
  // grouping logically by project and week on the application side if needed.

  // So the actually executable query in this context is equivalent to the
  // reference (without SQL GROUP BY):

  auto res =
      select_from<Project, "t1">(
          project_id_c,
          name_c,
          day(start_c),
          month(start_c),
          year(start_c),
          hour(start_c),
          minute(start_c),
          second(start_c),
          days_between(start_c, end_c)) |
      inner_join<TimeLog, "t2">(project_id_c == "project_id"_t2) |
      // We still invoke group_by(...) so the transpiler emits GROUP BY on
      // project and "week" if supported, but since we don't have week()
      // in the provided ops, we'll group by project_id and name only
      // to satisfy "Group by project and week for reporting" as closely
      // as possible with available primitives.
      group_by(project_id_c, name_c) |
      to<std::vector<TimeMetrics>>()(conn);

  // If the query failed, return an empty vector. In a real application,
  // you'd likely propagate or log the error.
  if (!res) {
    return {};
  }

  return *res;
}

}  // namespace project_time_tracking
