/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlite::connect("test_db.sqlite");

  // Build the query:
  //
  // SELECT
  //   u.user_id,
  //   u.name,
  //   COUNT(p.post_id) AS post_count,
  //   AVG(LENGTH(p.content)) AS avg_length
  // FROM User u
  // LEFT JOIN Post p ON u.user_id = p.user_id
  // GROUP BY u.user_id, u.name;
  //
  // We map the result columns into Stats by using the same field names.
  auto query =
      select_from<User, "u">(
          "user_id"_t1 | as<"user_id">,
          "name"_t1 | as<"name">,
          count("post_id"_t2) | as<"post_count">,
          avg("length(content)"_c) | as<"avg_length">) |
      join<Post, "t2">("user_id"_t1 == "user_id"_t2, JoinType::left) |
      group_by("user_id"_t1, "name"_t1) |
      to<std::vector<Stats>>;

  auto res = query(conn_res);

  if (!res) {
    // On error, return an empty vector. In a real application, you might throw
    // or propagate the error instead.
    return {};
  }

  return *res;
}

